+// Parses an optional whole-number query parameter; undefined when absent, NaN when malformed or out of range.
+function wholeParam(query, name, min, max) {
+  if (!query.has(name)) return undefined;
+  const raw = query.get(name);
+  if (!/^\d+$/.test(raw)) return NaN;
+  const n = Number(raw);
+  return n < min || n > max ? NaN : n;
+}
